  return items.map((item, index) => ({
    id: `${prefix}-${index + 1}-${Date.now()}`,
    title: item.title,
    description: item.description,
    mediaUrl: '',
    mediaType: index % 2 === 0 ? 'audio' : 'video',
    createdAt: new Date().toISOString()
  }));
};

